$root=dirname(__DIR__); require $root.'/src/Helpers/Env.php'; Env::load($root.'/.env');if(is_file($root.'/vendor/autoload.php'))require_once $root.'/vendor/autoload.php';
spl_autoload_register(function($class)use($root){$prefix='App\\';if(str_starts_with($class,$prefix)){$file=$root.'/src/'.str_replace('\\','/',substr($class,strlen($prefix))).'.php';if(is_file($file))require $file;}});
$secure=filter_var(Env::get('SESSION_SECURE','false'),FILTER_VALIDATE_BOOLEAN);session_name((string)Env::get('SESSION_NAME','pasteleria_session'));session_set_cookie_params(['httponly'=>true,'secure'=>$secure,'samesite'=>'Lax']);session_start();
